<?php
namespace Tests\Feature;
use App\Models\{User,TutorGroup,Apprentice,TrainingSession,AttendanceMark,TimetableChangeBatch as B};
use App\Support\{TimetableChanges as T,RegisterActions as R};
use Illuminate\Foundation\Testing\LazilyRefreshDatabase;
use Illuminate\Support\Facades\{DB,Crypt,Notification};
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;
use Tests\Support\AuditFault;
use Tests\TestCase;
class TimetableChangesTest extends TestCase {
 use LazilyRefreshDatabase;
 protected function setUp():void {parent::setUp();$this->travelTo(\Carbon\Carbon::parse('2026-11-15 08:00:00'));}
 private function f():array {$m=User::factory()->create(['role'=>'admin']);$n=User::factory()->create(['role'=>'ceo']);$t=User::factory()->create(['role'=>'tutor']);$g=TutorGroup::factory()->create(['tutor_id'=>$t->id]);$a=Apprentice::factory()->create(['tutor_id'=>$t->id,'tutor_group_id'=>$g->id,'email'=>'PRIVATE-LEARNER@example.test']);$b=Apprentice::factory()->create(['tutor_id'=>$t->id,'tutor_group_id'=>$g->id]);$s=TrainingSession::factory()->create(['tutor_group_id'=>$g->id,'created_by'=>$m->id,'session_date'=>'2026-12-01','members'=>[$a->id],'planned_learning'=>'PRIVATE-PLANNED-BODY']);return compact('m','n','t','g','a','b','s');}
 private function p(array $f,string $mode='move',?array $ids=null,int $days=1,?string $request=null):B {return T::prepare($f['m'],1,$request??(string)Str::uuid(),$mode,$f['g']->id,$ids??[$f['s']->id],$mode==='move'?$days:0,'PRIVATE-CHANGE-REFERENCE');}
 private function apply(array $f,B $b):void {T::decide($f['n'],1,$b,$b->version,'apply','PRIVATE-INDEPENDENT-CHECK');}
 private function invalid(callable $c):void {try{$c();$this->fail('Invalid operation accepted');}catch(ValidationException){$this->assertTrue(true);}}
 public function test_move_preview_is_exact_encrypted_and_does_not_change_any_session_or_mark():void {$f=$this->f();Notification::fake();$old=$f['s']->fresh()->getAttributes();$b=$this->p($f);$this->assertTrue(T::fresh($b));$this->assertSame('2026-12-02',$b->source['rows'][0]['date']);$this->assertSame($old,$f['s']->fresh()->getAttributes());$raw=DB::table('timetable_change_batches')->value('source');$this->assertStringNotContainsString('PRIVATE-CHANGE',$raw);$this->assertStringNotContainsString('PRIVATE-LEARNER',Crypt::decryptString($raw));$this->assertStringNotContainsString('PRIVATE-PLANNED-BODY',Crypt::decryptString($raw));$this->assertDatabaseCount('attendance_marks',0);Notification::assertNothingSent();}
 public function test_peer_apply_moves_only_date_version_and_history_preserving_times_breaks_plan_roster():void {$f=$this->f();$old=$f['s']->fresh()->getAttributes();$b=$this->p($f);$this->apply($f,$b);$s=$f['s']->fresh();$this->assertSame('2026-12-02',$s->session_date->toDateString());foreach(['start_time','end_time','planned_learning','breaks','members','delivered_learning','state']as$key){$this->assertSame($old[$key],$s->getAttributes()[$key]);}$this->assertSame(2,$s->version);$this->assertTrue(T::applied($b->fresh()));$this->assertDatabaseCount('attendance_marks',0);$this->assertDatabaseHas('learning_events',['event'=>'timetable_move']);}
 public function test_creator_cannot_apply_or_reject_but_can_withdraw():void {$f=$this->f();$b=$this->p($f);foreach(['apply','reject']as$d){$this->invalid(fn()=>T::decide($f['m'],1,$b,1,$d,'Self'));}T::decide($f['m'],1,$b,1,'withdraw','Withdraw');$this->assertSame('Withdrawn',$b->fresh()->state);$this->assertSame(1,$f['s']->fresh()->version);}
 public function test_roster_preview_names_additions_removals_and_applies_without_profile_transfer():void {$f=$this->f();$f['a']->tutor_group_id=TutorGroup::factory()->create()->id;$f['a']->save();$aBefore=$f['a']->fresh()->getAttributes();$bBefore=$f['b']->fresh()->getAttributes();$b=$this->p($f,'roster');$row=$b->source['rows'][0];$this->assertSame([$f['b']->id],$row['added']);$this->assertSame([$f['a']->id],$row['removed']);$this->apply($f,$b);$this->assertSame([$f['b']->id],$f['s']->fresh()->members);$this->assertSame($aBefore,$f['a']->fresh()->getAttributes());$this->assertSame($bBefore,$f['b']->fresh()->getAttributes());$this->assertDatabaseCount('assignment_change_events',0);$this->assertDatabaseCount('attendance_marks',0);}
 public function test_same_roster_preview_is_not_an_unnecessary_change():void {$f=$this->f();$f['s']->members=[$f['a']->id,$f['b']->id];$f['s']->save();$this->invalid(fn()=>$this->p($f,'roster'));$this->assertDatabaseCount('timetable_change_batches',0);}
 public function test_cancel_applies_future_only_without_marks_or_otj():void {$f=$this->f();$b=$this->p($f,'cancel');$this->apply($f,$b);$this->assertSame('Cancelled',$f['s']->fresh()->state);$this->assertSame([$f['a']->id],$f['s']->fresh()->members);$this->assertDatabaseCount('attendance_marks',0);$this->assertNull($f['s']->fresh()->delivered_learning);$this->assertTrue(T::applied($b->fresh()));}
 public function test_past_started_marked_delivered_cancelled_and_bad_timing_sources_refuse():void {foreach(['past','started','marked','delivered','cancelled','timing']as$kind){$f=$this->f();$s=$f['s'];if($kind==='past'){$s->session_date='2026-11-01';}if($kind==='started'){$s->session_date='2026-11-15';$s->start_time='07:00';}if($kind==='delivered'){$s->delivered_learning='Already recorded learning';}if($kind==='cancelled'){$s->state='Cancelled';}if($kind==='timing'){$s->end_time='08:00';}$s->save();if($kind==='marked'){AttendanceMark::create(['training_session_id'=>$s->id,'apprentice_id'=>$f['a']->id,'recorded_by'=>$f['t']->id,'code'=>null]);}$this->invalid(fn()=>$this->p($f));}}
 public function test_target_past_zero_or_out_of_range_shift_refuses():void {$f=$this->f();foreach([0,-365,366]as$d){$this->invalid(fn()=>$this->p($f,'move',null,$d));}}
 public function test_invalid_session_ids_group_mode_duplicate_and_size_refuse():void {$f=$this->f();foreach([[],[$f['s']->id,$f['s']->id],range(1000,1050),[999999]]as$ids){$this->invalid(fn()=>$this->p($f,'move',$ids));}$this->invalid(fn()=>$this->p($f,'unknown'));$other=TrainingSession::factory()->create(['session_date'=>'2026-12-01']);$this->invalid(fn()=>$this->p($f,'move',[$other->id]));}
 public function test_saved_roster_shape_and_duplicate_entries_refuse():void {$f=$this->f();foreach([['bad'=>1],[$f['a']->id,$f['a']->id]]as$roster){$f['s']->members=$roster;$f['s']->save();$this->invalid(fn()=>$this->p($f,'roster'));}}
 public function test_inactive_group_or_teacher_blocks_move_but_manager_can_cancel_future():void {$f=$this->f();$f['g']->active=false;$f['g']->save();$this->invalid(fn()=>$this->p($f));$b=$this->p($f,'cancel');$this->apply($f,$b);$this->assertSame('Cancelled',$f['s']->fresh()->state);}
 public function test_group_teacher_overlap_blocks_move_without_disclosing_other_learners():void {$f=$this->f();$g=TutorGroup::factory()->create(['tutor_id'=>$f['t']->id]);TrainingSession::factory()->create(['tutor_group_id'=>$g->id,'session_date'=>'2026-12-02','members'=>[]]);$this->invalid(fn()=>$this->p($f));$this->assertSame('2026-12-01',$f['s']->fresh()->session_date->toDateString());}
 public function test_saved_learner_overlap_across_groups_blocks_roster_change():void {$f=$this->f();TrainingSession::factory()->create(['session_date'=>'2026-12-01','members'=>[$f['b']->id]]);$this->invalid(fn()=>$this->p($f,'roster'));}
 public function test_adjacent_non_overlapping_time_does_not_block_move():void {$f=$this->f();TrainingSession::factory()->create(['tutor_group_id'=>$f['g']->id,'session_date'=>'2026-12-02','start_time'=>'16:00','end_time'=>'17:00','members'=>[$f['a']->id]]);$this->assertTrue(T::fresh($this->p($f)));}
 public function test_new_conflict_after_preview_blocks_whole_application():void {$f=$this->f();$b=$this->p($f);TrainingSession::factory()->create(['tutor_group_id'=>$f['g']->id,'session_date'=>'2026-12-02']);$this->assertFalse(T::fresh($b));$this->invalid(fn()=>$this->apply($f,$b));$this->assertSame(1,$f['s']->fresh()->version);}
 public function test_changed_group_profile_roster_or_marks_stales_preview():void {foreach(['group','profile','marks']as$kind){$f=$this->f();$b=$this->p($f,'roster');if($kind==='group'){$f['g']->record_version++;$f['g']->save();}elseif($kind==='profile'){$f['b']->version++;$f['b']->save();}else{AttendanceMark::create(['training_session_id'=>$f['s']->id,'apprentice_id'=>$f['a']->id,'recorded_by'=>$f['t']->id]);}$this->assertFalse(T::fresh($b));$this->invalid(fn()=>$this->apply($f,$b));}}
 public function test_current_group_membership_change_stales_exact_roster_preview():void {$f=$this->f();$b=$this->p($f,'roster');Apprentice::factory()->create(['tutor_group_id'=>$f['g']->id,'tutor_id'=>$f['t']->id]);$this->assertFalse(T::fresh($b));$this->invalid(fn()=>$this->apply($f,$b));}
 public function test_clock_reaching_start_and_expiry_stop_preview_without_writing():void {$f=$this->f();$b=$this->p($f);$this->travel(25)->hours();$this->assertFalse(T::fresh($b));$this->assertSame('Pending',$b->fresh()->state);$this->invalid(fn()=>$this->apply($f,$b));}
 public function test_same_request_is_idempotent_and_reused_different_request_refuses():void {$f=$this->f();$id=(string)Str::uuid();$a=$this->p($f,'move',null,1,$id);$this->assertSame($a->id,$this->p($f,'move',null,1,$id)->id);$this->apply($f,$a);$this->assertSame($a->id,$this->p($f,'move',null,1,$id)->id);$this->invalid(fn()=>$this->p($f,'move',null,2,$id));$this->assertDatabaseCount('timetable_change_batches',1);}
 public function test_two_same_source_batches_cannot_both_apply():void {$f=$this->f();$a=$this->p($f);$b=$this->p($f);$this->apply($f,$a);$this->assertFalse(T::fresh($b));$this->invalid(fn()=>$this->apply($f,$b));$this->assertSame(2,$f['s']->fresh()->version);}
 public function test_two_row_failure_leaves_every_selected_session_unchanged():void {$f=$this->f();$s=TrainingSession::factory()->create(['tutor_group_id'=>$f['g']->id,'session_date'=>'2026-12-08','members'=>[$f['a']->id]]);$b=$this->p($f,'move',[$f['s']->id,$s->id]);$s->version++;$s->save();$this->invalid(fn()=>$this->apply($f,$b));$this->assertSame('2026-12-01',$f['s']->fresh()->session_date->toDateString());$this->assertSame('2026-12-08',$s->fresh()->session_date->toDateString());}
 public function test_learning_audit_and_final_event_failure_roll_back_every_session():void {foreach(['learning_events','timetable_change_events']as$table){$f=$this->f();$b=$this->p($f);AuditFault::install('tt_fault_'.$table,$table,'Synthetic failure',$table==='learning_events'?'timetable_move':'preview_apply');try{$this->apply($f,$b);$this->fail('Audit ignored');}catch(\Illuminate\Database\QueryException){}$this->assertSame(1,$f['s']->fresh()->version);$this->assertSame('Pending',$b->fresh()->state);}}
 public function test_expiry_plain_state_and_metadata_tamper_do_not_look_applied():void {$f=$this->f();$b=$this->p($f);DB::table('timetable_change_batches')->where('id',$b->id)->update(['state'=>'Applied']);$this->assertFalse(T::applied($b->fresh()));DB::table('timetable_change_batches')->where('id',$b->id)->update(['expires_at'=>now()->addDays(5)]);$this->assertFalse(T::intact($b->fresh()));}
 public function test_actor_auth_and_creator_authority_are_rechecked():void {$f=$this->f();$b=$this->p($f);$f['m']->auth_version=2;$f['m']->save();$this->assertFalse(T::fresh($b));$f['n']->auth_version=2;$f['n']->save();try{$this->apply($f,$b);$this->fail('Stale actor');}catch(\Symfony\Component\HttpKernel\Exception\HttpException $e){$this->assertSame(403,$e->getStatusCode());}}
 public function test_calendar_tutor_scope_and_minimal_export_hide_other_groups_and_notes():void {$f=$this->f();$other=TrainingSession::factory()->create(['session_date'=>'2026-12-03','name'=>'PRIVATE-OTHER-GROUP']);$this->actingAs($f['t'])->get('/session-operations')->assertOk()->assertSee($f['s']->name)->assertDontSee('PRIVATE-OTHER-GROUP')->assertDontSee('PRIVATE-LEARNER')->assertHeader('Referrer-Policy','no-referrer');$this->get('/session-operations/calendar.json')->assertOk()->assertJsonPath('learner_names_comments_and_case_notes_exported',false)->assertDontSee('PRIVATE-');}
 public function test_manager_preview_and_exports_render_and_other_roles_denied():void {$f=$this->f();$b=$this->p($f);$this->actingAs($f['m'])->get('/session-operations/changes/new?group='.$f['g']->id)->assertOk();$this->get('/session-operations/changes/'.$b->id)->assertOk()->assertSee('PRIVATE-CHANGE-REFERENCE');$this->get('/session-operations/changes/'.$b->id.'/handover.json')->assertOk()->assertDontSee('PRIVATE-')->assertJsonPath('private_names_notes_and_rosters_exported',false);foreach(['tutor','mentor','apprentice','employer','staff']as$role){$u=User::factory()->create(['role'=>$role]);$this->actingAs($u)->get('/session-operations/changes')->assertForbidden();$this->get('/session-operations/changes/'.$b->id)->assertForbidden();$this->post('/session-operations/changes',[])->assertForbidden();}}
 public function test_mixed_main_tutors_are_explicit_not_silently_reassigned():void {$f=$this->f();$f['b']->tutor_id=User::factory()->create(['role'=>'tutor'])->id;$f['b']->save();$b=$this->p($f,'roster');$this->assertTrue($b->source['mixed_main_tutors']);$this->apply($f,$b);$this->assertFalse(R::allowed($f['t'],$f['s']->fresh()));$this->assertNotSame($f['t']->id,$f['b']->fresh()->tutor_id);}
 public function test_cancelled_or_stale_pending_preview_can_be_rejected_or_withdrawn():void {$f=$this->f();$b=$this->p($f);$f['s']->version++;$f['s']->save();T::decide($f['n'],1,$b,1,'reject','Stale source');$this->assertSame('Rejected',$b->fresh()->state);$c=$this->p($f);T::decide($f['m'],1,$c,1,'withdraw','Withdraw');$this->assertSame('Withdrawn',$c->fresh()->state);}
 public function test_post_form_validation_and_read_only_gets():void {$f=$this->f();$this->actingAs($f['m'])->post('/session-operations/changes',[])->assertSessionHasErrors(['request_token','sessions','confirmed']);foreach(['/session-operations','/session-operations/changes','/session-operations/changes/new']as$url){$this->get($url)->assertOk();}$this->assertDatabaseCount('timetable_change_batches',0);$this->assertDatabaseCount('attendance_marks',0);}
 public function test_added_learner_training_date_context_is_visible_without_auto_status_decision():void {$f=$this->f();$f['b']->start_date='2027-01-11';$f['b']->planned_end_date='2030-01-11';$f['b']->save();$b=$this->p($f,'roster');$this->assertSame([$f['b']->id],$b->source['rows'][0]['date_warnings']);$this->actingAs($f['m'])->get('/session-operations/changes/'.$b->id)->assertOk()->assertSee('Check training-date context')->assertSee('2027-01-11');$this->assertDatabaseCount('attendance_marks',0);}

}
